import java.util.*;

class Solution {
  public List<Integer> filterRestaurants(
      int[][] restaurants, int veganFriendly, int maxPrice, int maxDistance) {
    List<int[]> selected = new ArrayList<>();
    for (int[] restaurant : restaurants)
      if (restaurant[2] >= veganFriendly
          && restaurant[3] <= maxPrice
          && restaurant[4] <= maxDistance) selected.add(restaurant);
    selected.sort(
        (a, b) -> a[1] != b[1] ? Integer.compare(b[1], a[1]) : Integer.compare(b[0], a[0]));
    List<Integer> result = new ArrayList<>();
    for (int[] restaurant : selected) result.add(restaurant[0]);
    return result;
  }
}
